<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Support\LegacyResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Throwable;
class EqMonitoringController extends Controller
{
 private function user(Request $r){return $r->attributes->get('jwt_user');}
 public function byEquipment($eqId){try{$rows=DB::table('equipment_monitoring_types')->where('equipment_id',$eqId)->where('is_active',true)->orderBy('display_order')->orderBy('id')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all();return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}
 public function create(Request $r,$eqId){$name=$r->input('monitoring_name');if(!$name)return response()->json(['success'=>false,'message'=>'Monitoring name is required'],400);try{$cols=$r->input('columns');if(!is_array($cols)||!count($cols))$cols=[['label'=>'Value']];$id=DB::table('equipment_monitoring_types')->insertGetId(['equipment_id'=>$eqId,'monitoring_name'=>$name,'unit'=>$r->input('unit')?:null,'reference_values'=>json_encode($r->input('reference_values',[])),'columns'=>json_encode($cols),'display_order'=>$r->input('display_order',1),'general_shift_only'=>filter_var($r->input('general_shift_only',false),FILTER_VALIDATE_BOOLEAN),'is_active'=>true,'is_unlocked'=>false,'created_at'=>now()]);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize(DB::table('equipment_monitoring_types')->where('id',$id)->first())]);}catch(Throwable $e){return $this->err($e);}}
 public function update(Request $r,$id){try{$cols=$r->input('columns');if(!is_array($cols)||!count($cols))$cols=[['label'=>'Value']];DB::table('equipment_monitoring_types')->where('id',$id)->update(['monitoring_name'=>$r->input('monitoring_name'),'unit'=>$r->input('unit')?:null,'reference_values'=>json_encode($r->input('reference_values',[])),'columns'=>json_encode($cols),'display_order'=>$r->input('display_order',1),'general_shift_only'=>filter_var($r->input('general_shift_only',false),FILTER_VALIDATE_BOOLEAN)]);$x=DB::table('equipment_monitoring_types')->where('id',$id)->first();if(!$x)return response()->json(['success'=>false,'message'=>'Not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($x)]);}catch(Throwable $e){return $this->err($e);}}
 public function destroy($id){try{DB::table('equipment_monitoring_types')->where('id',$id)->update(['is_active'=>false]);return response()->json(['success'=>true]);}catch(Throwable $e){return $this->err($e);}}
 public function today(Request $r){try{$q=DB::table('eq_monitoring_logs as ml')->join('equipment as e','e.id','=','ml.equipment_id')->where('ml.shift',$r->input('shift'))->whereDate('ml.logged_at',now()->toDateString());if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('department'))$q->where('e.department',$r->input('department'));return response()->json(['success'=>true,'data'=>$q->pluck('ml.monitoring_id')->map(fn($v)=>(int)$v)->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function last24(Request $r){try{$q=DB::table('eq_monitoring_logs as ml')->join('equipment_monitoring_types as em','em.id','=','ml.monitoring_id')->join('equipment as e','e.id','=','ml.equipment_id')->join('users as u','u.id','=','ml.logged_by')->select('ml.*','em.monitoring_name','em.unit','em.reference_values','em.columns','e.name as equipment_name','e.code as equipment_code','u.full_name as logged_by_name')->where('ml.logged_at','>=',now()->subHours(24));if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('department'))$q->where('e.department',$r->input('department'));return response()->json(['success'=>true,'data'=>$q->orderByDesc('ml.logged_at')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function log(Request $r){$mid=$r->input('monitoring_id');$eid=$r->input('equipment_id');$shift=$r->input('shift');$read=$r->input('readings');if(!$mid||!$eid||!$shift||!is_array($read)||!count($read))return response()->json(['success'=>false,'message'=>'monitoring_id, equipment_id, shift, readings required'],400);try{if(DB::table('eq_monitoring_logs')->where('monitoring_id',$mid)->where('shift',$shift)->where('logged_date',now()->toDateString())->exists())return response()->json(['success'=>false,'message'=>'Already submitted for this shift'],409);$id=DB::table('eq_monitoring_logs')->insertGetId(['monitoring_id'=>$mid,'equipment_id'=>$eid,'plant'=>$r->input('plant'),'department'=>$r->input('department')?:null,'shift'=>$shift,'logged_by'=>$this->user($r)->id,'readings'=>json_encode($read),'remarks'=>$r->input('remarks')?:null,'logged_date'=>now()->toDateString(),'logged_at'=>now()]);return response()->json(['success'=>true,'data'=>['id'=>$id]]);}catch(Throwable $e){return $this->err($e);}}
 public function all(Request $r){try{$q=DB::table('equipment_monitoring_types as em')->join('equipment as e','e.id','=','em.equipment_id')->leftJoin('users as u','u.id','=','em.unlocked_by')->select('em.*','e.name as equipment_name','e.code as equipment_code','e.department','e.location','e.plant','u.full_name as unlocked_by_name')->where('e.active',true)->where('em.is_active',true);if($r->filled('plant'))$q->where('e.plant',$r->input('plant'));if($r->filled('department'))$q->where('e.department',$r->input('department'));return response()->json(['success'=>true,'data'=>$q->orderBy('e.department')->orderBy('e.name')->orderBy('em.display_order')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all()]);}catch(Throwable $e){return $this->err($e);}}
 public function locked(){try{$rows=DB::table('equipment_monitoring_types as em')->join('equipment as e','e.id','=','em.equipment_id')->leftJoin('users as u','u.id','=','em.unlocked_by')->select('em.id','em.monitoring_name','em.general_shift_only','em.is_unlocked','em.unlocked_at','em.unlock_note','e.name as equipment_name','e.code as equipment_code','e.plant','e.department','u.full_name as unlocked_by_name')->where('em.general_shift_only',true)->orderBy('e.plant')->orderBy('e.department')->orderBy('e.name')->orderBy('em.monitoring_name')->get()->map(fn($x)=>LegacyResponse::normalize($x))->all();return response()->json(['success'=>true,'data'=>$rows]);}catch(Throwable $e){return $this->err($e);}}
 public function unlock(Request $r,$id){try{DB::table('equipment_monitoring_types')->where('id',$id)->update(['is_unlocked'=>true,'unlocked_by'=>$this->user($r)->id,'unlocked_at'=>now(),'unlock_note'=>$r->input('unlock_note')?:null]);$x=DB::table('equipment_monitoring_types')->select('id','monitoring_name','is_unlocked')->where('id',$id)->first();if(!$x)return response()->json(['success'=>false,'message'=>'Not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($x)]);}catch(Throwable $e){return $this->err($e);}}
 public function lock($id){try{DB::table('equipment_monitoring_types')->where('id',$id)->update(['is_unlocked'=>false,'unlocked_by'=>null,'unlocked_at'=>null,'unlock_note'=>null]);$x=DB::table('equipment_monitoring_types')->select('id','monitoring_name','is_unlocked')->where('id',$id)->first();if(!$x)return response()->json(['success'=>false,'message'=>'Not found'],404);return response()->json(['success'=>true,'data'=>LegacyResponse::normalize($x)]);}catch(Throwable $e){return $this->err($e);}}
 private function err(Throwable $e){return response()->json(['success'=>false,'message'=>$e->getMessage()],500);}
}
